const browser = await agent.browsers.get('iab');
const tab = await browser.tabs.new();
await tab.goto('{{browserFixtureUrl}}');
await tab.setViewportSize({ width: 1280, height: 720 });
await new Promise(resolve => setTimeout(resolve, 1200));
const png = await tab.screenshot();
await nodeRepl.emitImage(png);
for (const point of [{x:300,y:200},{x:600,y:400},{x:1000,y:600}]) await tab.cua.click(point);
const page = await tab.playwright.evaluate(() => ({ events: window.zoomEvents, width: innerWidth, height: innerHeight, dpr: devicePixelRatio }));
const { request } = await import('node:http');
await new Promise((resolve, reject) => { const req = request('{{browserFixtureUrl}}result/0', { method: 'POST' }, res => { res.resume(); res.on('end', resolve); }); req.on('error', reject); req.end(JSON.stringify({ png: Buffer.from(png).toString('base64'), page, tabId: tab.id })); });
({ marker: 'E2E_ZOOM_RESULT_0', e2eBrowserTabId: tab.id });

