const { Buffer } = await import('node:buffer');
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const root = process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { setupBrowserRuntime } = await import(pathToFileURL(join(root, 'scripts', 'browser-client.mjs')).href);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.get('iab');
const tab = await browser.tabs.get('{{latestBrowserTabId}}');
const png = await tab.screenshot();
const before = await tab.playwright.evaluate(() => window.facts());
const { request } = await import('node:http');
const post = (path, data) => new Promise((resolve, reject) => { const req = request('{{browserFixtureUrl}}' + path, { method: 'POST' }, res => { res.resume(); res.on('end', resolve); }); req.on('error', reject); req.end(JSON.stringify(data)); });
await post('recovery-prepare', { png: Buffer.from(png).toString('base64'), before, tabId: tab.id });
await tab.cua.click({x:100, y:200});
const after = await tab.playwright.evaluate(() => window.facts());
const events = await tab.playwright.evaluate(() => window.events);
await post('recovery-result', { after, events, tabId: tab.id });
({ marker: 'E2E_ZOOM_RECOVERY_RESULT', e2eBrowserTabId: tab.id });
